fn comb_sort(var nums: [int]) -> [int]:
    shrink_fact = 1.3
    var gaps = len(nums)
    var swapped = True
    var i = 0
    while gaps > 1 or swapped:
        gaps = int(float(gaps) / shrink_fact)
        swapped = False
        i = 0
        while gaps + i < len(nums):
            if nums[i] > nums[i + gaps]:
                (nums[i], nums[i + gaps]) = (nums[i + gaps], nums[i])
                swapped = True
            i += 1
    return nums

fn maxAverageOfPath(cost: [[int]]) -> f64:
    N = len(cost)
    var dp = [[0 for i in range(N + 1)] for j in range(N + 1)]
    dp[0][0] = cost[0][0]
    for i in range(1, N):
        dp[i][0] = dp[i - 1][0] + cost[i][0]
    for j in range(1, N):
        dp[0][j] = dp[0][j - 1] + cost[0][j]
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j]
    return dp[N - 1][N - 1] / (2 * N - 1)

